#include <iostream>
using namespace std;

int main() {
    long long n, m;
    cin >> n >> m;

    if (m % n != 0) {
        cout << -1;
        return 0;
    }

    long long k = m / n;
    int ans = 0;

    while (k % 2 == 0) {
        k /= 2;
        ++ans;
    }
    while (k % 3 == 0) {
        k /= 3;
        ++ans;
    }

    cout << (k == 1 ? ans : -1);
    return 0;
}

